def stripe_secret_key():
    key = os.environ.get("STRIPE_TEST_KEY")
    if not key:
        raise RuntimeError("Set the STRIPE_TEST_KEY environment variable to your Stripe test secret key.")
    return key

def form_url_encode(data):
    pairs = []

    def add(key, value):
        if value is None:
            return
        if isinstance(value, dict):
            for k, v in value.items():
                add(f"{key}[{k}]", v)
        elif isinstance(value, (list, tuple)):
            for i, v in enumerate(value):
                add(f"{key}[{i}]", v)
        elif isinstance(value, bool):
            pairs.append((key, "true" if value else "false"))
        else:
            pairs.append((key, value))

    for k, v in (data or {}).items():
        add(k, v)
    return urllib.parse.urlencode(pairs)

def extract_field_async(response, field_path, as_type="str"):
    code = getattr(response, "status_code", 0)
    print(f"PASS: status {code}" if code in (200, 201) else f"FAIL: expected 200 or 201 but got {code}")
    data = response.json()
    for part in [p for p in re.split(r"[.\[\]]+", field_path) if p]:
        if isinstance(data, list) and part.lstrip("-").isdigit():
            index = int(part)
            data = data[index] if -len(data) <= index < len(data) else None
        elif isinstance(data, dict):
            data = data.get(part)
        else:
            data = None
    if data is None:
        return "" if as_type == "str" else None
    if as_type == "int":
        return int(float(data))
    if as_type == "float":
        return float(data)
    if as_type == "bool":
        return data if isinstance(data, bool) else str(data).strip().lower() in ("true", "1", "yes")
    return str(data)

def delete_by_path_value_async(token, url_template, value):
    url = re.sub(r"\{[^}]+\}", urllib.parse.quote(value, safe=""), url_template, count=1)
    return reporter.record(requests.delete(url, headers={"Authorization": f"Bearer {token}", "Accept": "application/json"}))

def upload_file_async(token, url, file_path, file_field_name):
    with open(file_path, "rb") as fh:
        files = {file_field_name: (os.path.basename(file_path), fh)}
        return reporter.record(requests.post(url, headers={"Authorization": f"Bearer {token}", "Accept": "application/json"}, files=files))
